class Solution {
    private static final int INF = Integer.MAX_VALUE;

    public int coinChange(int[] coins, int amount) {
        int r = f(coins, amount);
        return r == INF ? -1 : r;
    }

    private int f(int[] coins, int rest) {
        if (rest == 0) return 0;
        if (rest < 0) return INF;
        int best = INF;
        for (int c : coins) {
            int sub = f(coins, rest - c);
            if (sub != INF) best = Math.min(best, sub + 1);
        }
        return best;
    }
}

class Solution {
    public int coinChange(int[] coins, int amount) {
        int[] memo = new int[amount + 1];
        for (int i = 0; i <= amount; i++) memo[i] = amount + 1;
        int r = f(coins, amount, memo);
        return r > amount ? -1 : r;
    }

    private int f(int[] coins, int rest, int[] memo) {
        if (rest == 0) return 0;
        if (rest < 0) return memo.length;
        if (memo[rest] != memo.length) return memo[rest];

        int best = memo.length;
        for (int c : coins) {
            best = Math.min(best, f(coins, rest - c, memo) + 1);
        }
        memo[rest] = best;
        return best;
    }
}

class Solution {
    public int coinChange(int[] coins, int amount) {
        int INF = amount + 1;
        int[] dp = new int[amount + 1];
        for (int i = 1; i <= amount; i++) dp[i] = INF;

        for (int i = 1; i <= amount; i++) {
            for (int c : coins) {
                if (c > i) continue;
                if (dp[i - c] == INF) continue;
                dp[i] = Math.min(dp[i], dp[i - c] + 1);
                if (dp[i] == 1) break;
            }
        }
        return dp[amount] > amount ? -1 : dp[amount];
    }
}
